        """Set topic nodes for the visualization."""
        self._nodes = []
        if not topics:
            self.update()
            return

        for i, topic in enumerate(topics[:12]):
            angle = (2 * math.pi * i) / min(len(topics), 12)
            self._nodes.append({
                "label": topic[:18],
                "angle": angle,
                "radius_offset": (hash(topic) % 30) / 100.0,
                "speed": 0.002 + (hash(topic) % 10) * 0.0003,
            })
        self.update()

