def set_topics(self, topics: List[str]):
    """Set topic nodes for the visualization."""
    self._nodes = []
    if not topics:
        self.update()
        return

    topics = topics[:12]
    angles = [(2 * math.pi * i) / min(len(topics), 12) for i in range(len(topics))]
    node_data = [
        {
            "label": topic[:18],
            "angle": angle,
            "radius_offset": (hash(topic) % 30) / 100.0,
            "speed": 0.002 + (hash(topic) % 10) * 0.0003,
        }
        for i, (topic, angle) in enumerate(zip(topics, angles))
    ]
    self._nodes = node_data
    self.update()

